def _pseudo_m(T):
    k = lambda s: f'<span class="kw">{s}</span>'
    c = lambda s: f'<span class="cm"># {s}</span>'
    return f"""{k(T("CONSTANTES de M1 e M2", "M1 and M2 CONSTANTS"))}   M_MAX = 5   BANDS_E = [0], [1], [2–3], [4–7], [8–15]   λ_RLS = 0.999   δ_RLS = 100
              EVERY = 8   CLIP_K = 2   N_MIN = 100   T_MAX = 5000   LAM = 0.99   SCALE_FLOOR = 0.1   ε_gate = 0.002   α_gate = 0.01

{k(T("PREVER", "PREDICT"))}(x_t):
  L ← {T("núcleo.prever", "core.predict")}(x_t)                              {c(T("pseudocódigo do núcleo acima", "core pseudocode above"))}
  {c(T("M1: especialista de precisão", "M1: precision expert"))}
  x ← {T("x_t com ausentes trocados pelo último valor visto", "x_t with missing values replaced by the last value seen")}
  z ← [1, ỹ_(t−1), ỹ_(t−2), {T("médias das BANDS_E das m = mín(d, M_MAX) entradas escolhidas, padronizadas", "BANDS_E means of the m = min(d, M_MAX) chosen inputs, standardised")}]
  E ← clip(w·z, L ± CLIP_K·max(σ̂_L, {T("piso", "floor")}))      {k(T("se", "if"))} {T("RLS determinada (n_RLS ≥ k = 3 + 5m)", "RLS determined (n_RLS ≥ k = 3 + 5m)")}
  L' ← L {k(T("se", "if"))} E {T("indefinido ou", "undefined or")} AdaHedge₁.n < N_MIN; {T("senão", "else")} (1 − ω)·L + ω·E      {c(T("sombra", "shadow"))}
  {c(T("M2: ponto de partida na referência trivial", "M2: start from the trivial reference"))}
  R ← 0 | y_last | y_(t−s)                                 {c(T("zero, persistência ou sazonal ingênuo, declarada", "zero, persistence or seasonal naive, declared"))}
  {k(T("se", "if"))} R {T("indefinida", "undefined")}: ŷ ← L'
  {T("senão", "else")}: H ← w_H·[R, L'];  W ← w_W·[R, L'];  s ← η·w_A / (η·w_A + w_B/2);  ŷ ← s·W + (1 − s)·H
  {k(T("retorna", "return"))} ŷ, [ŷ − q̂_o, ŷ + q̂_o]

{k(T("OBSERVAR", "OBSERVE"))}(y_t, quarantine):
  {T("núcleo.observar", "core.observe")}(y_t, quarantine)
  {k(T("se", "if"))} y_t {T("observado", "observed")}:
    AdaHedge₁.update((y_t − L)², (y_t − E)²)                  {c(T("erro quadrático sem recorte", "squared error, no clipping"))}
    learn ← ¬quarantine ∧ {T("entradas dentro do contrato", "inputs within the contract")}
    {k(T("se", "if"))} learn: {T("a cada EVERY alvos: triagem (médias exponenciais 1 − LAM) e RLS(z, y_t)", "every EVERY targets: screening (exponential means 1 − LAM) and RLS(z, y_t)")}
             {T("seleção das m entradas depois de N_MIN alvos e a cada T_MAX; se mudar: RLS e AdaHedge₁ recomeçam", "selection of the m inputs after N_MIN targets and every T_MAX; if it changes: RLS and AdaHedge₁ restart")}
    {k(T("se", "if"))} ¬quarantine ∧ R {T("definida", "defined")}:
      AdaHedge_H.update((y_t − R)², (y_t − L')²)
      s² ← max(min(σ̂²_R, σ̂²_L'), {T("piso", "floor")}²);  Switch_W.update((y_t − R)²/2s², (y_t − L')²/2s²)   {c(T("reserva em escala log contra 0/0", "log-scale fallback against 0/0"))}
      N ← max(LAM·N, (y_t − H)², (y_t − W)²);  Prod.update((y_t − H)²/N, (y_t − W)²/N)
      gate.observe(...)                                       {c(T("auditoria: registra eventos, não decide a saída", "audit: logs events, does not decide the output"))}
    {T("intervalo da saída", "output interval")}: miss ← |y_t − ŷ| > q̂_o;  {k(T("a cada", "every"))} EVERY: q̂_o ← max(0, q̂_o + 0.1·σ̂_o·Σ(miss − 0.1))"""


def _pseudo_54(T):
    k = lambda s: f'<span class="kw">{s}</span>'
    c = lambda s: f'<span class="cm"># {s}</span>'
    return f"""{k(T("M1 DORMENTE", "DORMANT M1"))} {c(T("substitui a M1 acima quando dorme", "replaces M1 above while asleep"))}
  {k(T("se", "if"))} {T("ativa", "active")} ∧ {T("após a sombra", "after the shadow")} ∧ ω < 10⁻³ {T("por", "for")} D {T("alvos seguidos", "consecutive targets")}: {T("dormir", "sleep")}            {c(T("D = 2.000; D = 500 em teste", "D = 2,000; D = 500 in trial"))}
  {k(T("se", "if"))} {T("dormindo", "asleep")}: L' ← L
    {k(T("a cada", "every"))} 8 {T("alvos", "targets")}: E {T("calculado", "computed")}; g ← ((y − L)² − (y − E)²)/(y − L)²;  ḡ ← ḡ + 0.01·(g − ḡ)
    {k(T("a cada", "every"))} 64 {T("alvos", "targets")}: RLS(z, y)
    {k(T("se", "if"))} ḡ > 0.05 ∧ {T("amostras", "samples")} ≥ 100: {T("despertar; AdaHedge₁ recomeça com sombra", "wake; AdaHedge₁ restarts with shadow")}
    {k(T("se", "if"))} {T("a seleção de entradas mudou", "the input selection changed")}: {T("despertar em teste", "wake in trial")}

{k(T("REMOÇÃO DISPARADA", "TRIGGERED REMOVAL"))} {c(T("a cada decisão do núcleo, antes do calendário periódico", "at each core decision, before the periodic schedule"))}
  {k(T("para cada", "for each"))} {T("unidade ativa", "active unit")} u: ref_u ← max(ref_u, contrib_u)
  {k(T("se", "if"))} contrib_u < 0.5·ref_u ∧ {T("≥ 2.000 passos desde o último teste disparado de u", "≥ 2,000 steps since u's last triggered test")} ∧ {T("u livre ou só em teste periódico de remoção", "u free or only in a periodic removal test")}:
    {T("encerrar o teste periódico de u (a hipótese persistente fica)", "close u's periodic test (the persistent hypothesis is kept)")}
    {T("abrir episódio com hipótese nova; nível", "open an episode with a new hypothesis; level")} α·γ_k·(R^rem + 1);  ref_u ← contrib_u
    {T("aceitar se", "accept if")} log E ≥ log(1/α_k) ∧ {T("passos de evidência", "evidence steps")} ≥ 5.000;  {T("encerrar em 10.000 ou pela varredura", "close at 10,000 or by the scan rule")}

{k(T("RELATÓRIO DE EQUIVALENTES", "EQUIVALENCE REPORT"))}
  {k(T("a cada", "every"))} 31 {T("passos", "steps")}: {T("aplicar as linhas pendentes", "apply the pending rows")}; m ← m + 0.031·(x − m);  xc ← x − m
  {k(T("a cada passo", "every step"))}: {T("aplicar xc a até ⌈d/30⌉ linhas", "apply xc to up to ⌈d/30⌉ rows")} i: C[i, j≥i] ← C[i, j≥i] + 0.031·(xc_i·xc_j − C[i, j≥i]); {T("espelhar", "mirror")}
  {k(T("consulta", "query"))}: {T("aplicar as linhas pendentes; grupo de u = entradas com |correlação| ≥ 0,95", "apply the pending rows; group of u = inputs with |correlation| ≥ 0.95")}"""


def _pseudo_55(T):
    k = lambda s: f'<span class="kw">{s}</span>'
    c = lambda s: f'<span class="cm"># {s}</span>'
    return f"""{k(T("NÚCLEO ANCORADO (v0.55)", "ANCHORED CORE (v0.55)"))} {c(T("substitui as linhas correspondentes do núcleo", "replaces the corresponding core lines"))}
  {k(T("PREVER", "PREDICT"))}:  m ← {T("memória", "memory")};  s ← {T("estrutura de nível", "level structure")};  ŝΔ ← base_Δ·[1, x_t] + Σ_u w_Δ,u·{T("bloco", "block")}_u
            L₁ ← m + wS·(s − m);   L ← L₁ + wI·((m + ŝΔ) − L₁)                 {c(T("depois, o envelope de saída", "then the output envelope"))}
            {k(T("para cada", "for each"))} {T("experimento", "experiment")}: R ← s {k(T("se", "if"))} {T("a unidade é interna", "the unit is internal")} {k(T("senão", "else"))} L
              c_u ← (1 − wI)·wS·w_u·b_u + wI·w_Δ,u·b_u   {c(T("contribuição de uma unidade externa em L", "contribution of an external unit in L"))}
              g ← R + a − c_u                                {c(T("adição: a; remoção: c_u", "addition: a; removal: c_u"))}
  {k(T("OBSERVAR", "OBSERVE"))}:  {T("piso", "floor")} ← 0.1·√min(v_nível, v_Δy)   {c(T("calculado antes de ver y_t", "computed before seeing y_t"))};  B ← 2·max(σ̂_L, {T("piso", "floor")})
            d ← min((y − R)²/B², 1) − min((y − g)²/B², 1) − ε;   {T("desafiante aprende", "challenger learns")} (y − R) + c_u
            NLMS(s; y − s);  NLMS(ŝΔ; y − (m + ŝΔ))                       {c(T("mesmos atributos e denominador, μ = 0,05", "same features and denominator, μ = 0.05"))}
            D_I ← 0.99·D_I + ((y − m − ŝΔ)² − (y − L₁)²)/σ̂²;  {k(T("a cada", "every"))} 8: wI ← 1/(1 + e^(0.5·D_I))
            {T("triagem: externas e internas com o resíduo", "screening: external and internal units with the residual")} y − L   {c(T("portão suave", "soft gate"))}
  {k(T("ACEITAR", "ACCEPT"))}: {T("a unidade entra em s com os pesos do desafiante; em ŝΔ com os mesmos pesos se for externa, com zero se for interna", "the unit enters s with the challenger's weights; ŝΔ with the same weights if external, with zero if internal")}"""


def sections(lang, N, Dg, G):
    P = lang == "pt"
    T = lambda pt, en: pt if P else en
    F = N["final53"]; fam = F["fam"]; f6 = N["f6"]; dev = N["dev"]; val = N["val"]; sh = N["shocks"]; B = N["base"]
    F4 = N["final54"]; fam4 = F4["fam"]; D4 = N["dev54"]; AU = N["audit"]; AA = AU["A"]
    F5 = N["final55"]; fam5 = F5["fam"]; V5 = N["val55"]; CP = N["comp55"]; BK = N["bench55"]; C1 = BK["C1_summary"]; cr5 = F5["crit"]
    FN = FAM[lang]; mn = MN[lang]; cmn = CMN[lang]

    def n(x, d=3):
        s = f"{x:,.{d}f}"
        return s.replace(",", "X").replace(".", ",").replace("X", ".") if P else s

    def ci(a):
        return "-" if not a else f"{n(a['geo'])} [{n(a['ic95'][0])}; {n(a['ic95'][1])}]"

    def ci_s(s):
        lo, hi = (float(v) for v in s.strip("[]").split(","))
        return f"[{n(lo)}; {n(hi)}]"

    def tbl(head, rows, cls="compact", hl=None):
        h = "".join(f"<th>{c}</th>" for c in head)
        body = "".join(('<tr class="highlight-row">' if hl and hl(r) else "<tr>") + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows)
        return f'<table class="no-break {cls}"><thead><tr>{h}</tr></thead><tbody>{body}</tbody></table>'

    def fig(s, cap):
        return f'<div class="diagram-container no-break">{s}<div class="diagram-caption">{cap}</div></div>'

    # ---------------- numbers of the whole LEBRE (final evaluation)
    ov = F["overall"]
    inc_med, inc_max = float(np.median(F["inc_all"])), float(max(F["inc_all"]))
    c_med, c_max, c_min = float(np.median(F["cost_all"])), float(max(F["cost_all"])), float(min(F["cost_all"]))
    cc_med = float(np.median(F["core_cost_all"]))
    nm = F["ram_info"]["numeros_m1"] + F["ram_info"]["numeros_m2"]
