    au_t5 = AA["T5"]; au_t2 = AA["T2"]
    # ---------------- numbers of the structural core (its own evaluations)
    t3, p3, pf, r3m = B["r3_tab"], B["r3_pair"], B["r3_pair_fm"], B["r3_meta"]
    t2, t1, mcu = B["r2_tab"], B["r1_tab"], B["mcu"]
    g1 = B["r3p_gm"]
    fp3 = float(r3m.fp.mean()); fpmax3 = float(r3m.fp_max.max())
    ttm0, ttm1 = B["ttm_flops"]
    imin, imax = float(mcu["mean"].min()), float(mcu["mean"].max())
